def find_maximal_perfect_rectangles(grid):
    """Find all maximal perfect rectangles of each color."""
    h, w = len(grid), len(grid[0])
    rects = {}

    # Initialize with empty lists for each color
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in rects:
                rects[color] = []

    for color in list(rects.keys()):
        for r_start in range(h):
            for c_start in range(w):
                if grid[r_start][c_start] != color:
                    continue

                max_r, max_c = r_start, c_start
                while max_r + 1 < h:
                    max_c_next = c_start
                    for c_try in range(c_start, w):
                        if grid[max_r+1][c_try] == color:
                            max_c_next = c_try
                        else:
                            break
                    if max_c_next >= max_c:
                        max_r += 1
                        max_c = max_c_next
                    else:
                        break

                area = (max_r - r_start + 1) * (max_c - c_start + 1)
                rects.setdefault(color, []).append(((r_start, c_start, max_r, max_c), area))

    return rects

