print("\n=== Checking 4-way connected components of same color ===")
from collections import deque

def get_4_connected_components(g):
    h, w = len(g), len(g[0])
    visited = set()
    components = []

    for r in range(h):
        for c in range(w):
            if (r,c) in visited:
                continue

            color = g[r][c]
            comp = deque([(r,c)])
            vis_this_comp = {(r,c)}

            while comp:
                cr, cc = comp.popleft()
                visited.add((cr,cc))

                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in visited and g[nr][nc] == color:
                        vis_this_comp.add((nr,nc))
                        comp.append((nr,nc))

            components.append((len(vis_this_comp), vis_this_comp, color))

    return components

